def scrape_article(url): """抓取新闻文章""" with SeleniumHelper(headless=True) as helper: helper.get_page(url) # 等待内容加载 WebDriverWait(helper.driver, 20).until( EC.presence_of_element_located((By.TAG_NAME, "article")) ) # 抓取标题 title_element = helper.find_element_safe(By.TAG_NAME, "h1") title = title_element.text if title_element else "无标题" # 抓取作者 author_element = helper.find_element_safe(By.CSS_SELECTOR, ".author") author = author_element.text if author_element else "未知作者" # 抓取发布日期 date_element = helper.find_element_safe(By.CSS_SELECTOR, ".date") date = date_element.text if date_element else "未知日期" # 抓取正文 content_element = helper.find_element_safe(By.TAG_NAME, "article") content = content_element.text if content_element else "" # 清理文本 content = content.replace('


', '

') return { 'title': title, 'author': author, 'date': date, 'content': content, 'url': url }
